  1	package checkpoint
  2	
  3	import (
  4		"context"
  5		"errors"
  6		"fmt"
  7		"math/rand/v2"
  8		"os"
  9		"os/exec"
 10		"sort"
 11		"strings"
 12		"sync"
 13		"time"
 14	
 15		"github.com/go-git/go-git/v6"
 16		"github.com/go-git/go-git/v6/plumbing"
 17	)
 18	
 19	// ErrRefConflict identifies a native Git compare-and-swap failure.
 20	var ErrRefConflict = errors.New("git ref moved during update")
 21	
 22	// ErrRefMoveConflict identifies a failed source/destination ref move.
 23	var ErrRefMoveConflict = errors.New("git ref move conflict")
 24	
 25	const (
 26		refTransactionMaxAttempts = 16
 27		refTransactionMaxJitter   = 8 * time.Millisecond
 28	)
 29	
 30	// repositoryObjectLocks protects go-git's repository-local filesystem object
 31	// cache. Native Git CAS remains the cross-process ref-publication boundary.
 32	var repositoryObjectLocks sync.Map
 33	
 34	func repositoryObjectLock(repo *git.Repository) *sync.Mutex {
