104	func (s *kindRoutingStore) Read(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
105		return firstResolved(s.readOrder(checkpointID),
106			func(st PersistentStore) (*CheckpointSummary, error) { return st.Read(ctx, checkpointID) },
107			checkpointNotFound,
108		)
109	}
