255	func (s *gitRefsStore) checkpointTreeAt(commitHash plumbing.Hash, checkpointID id.CheckpointID) (*object.Tree, error) {
256		if commitHash.IsZero() {
257			return nil, nil //nolint:nilnil // new checkpoint ref
258		}
