271	// tree (which is the checkpoint subtree itself). Returns ErrCheckpointNotFound
272	// when the ref or its commit/tree cannot be resolved.
273	func (s *gitRefsStore) checkpointTree(ctx context.Context, cid id.CheckpointID) (*FetchingTree, error) {
274		if err := ctx.Err(); err != nil {
275			return nil, err //nolint:wrapcheck // Propagating context cancellation
276		}
277		ref, err := s.resolveRefMaybeFetch(ctx, cid)
278		if err != nil {
279			if errors.Is(err, plumbing.ErrReferenceNotFound) {
280				return nil, ErrCheckpointNotFound
281			}
282			return nil, err
283		}
284		commit, err := s.repo.CommitObject(ref.Hash())
285		if err != nil {
286			// The ref resolved but its commit object doesn't — corruption/IO, not an
287			// absent checkpoint. Surface it instead of masking as "not found".
288			return nil, fmt.Errorf("read checkpoint commit %s for %s: %w", ref.Hash(), cid, err)
289		}
290		tree, err := commit.Tree()
291		if err != nil {
292			return nil, fmt.Errorf("read checkpoint tree for %s: %w", cid, err)
293		}
294		return NewFetchingTree(ctx, tree, s.repo.Storer, s.blobFetcher), nil
295	}
