118	// enqueueForPush records refName in the push-discovery queue, logging (never
119	// returning) on failure so the local ref write still succeeds.
120	//
121	// The queue is resolved with the cancellation stripped from ctx. By the time we
122	// get here the ref is already written locally, and the queue is the ONLY
123	// push-discovery mechanism there is — see the
124	// pushQueueFileName doc. A ref that misses the queue is never pushed, and the
125	// writers above are idempotent, so a re-run skips it as already-present and
126	// never re-enqueues it: it stays local-only forever. Resolving the queue shells
127	// out to `git rev-parse --git-common-dir`, which fails instantly on a canceled
128	// ctx, so honoring cancellation here would drop the bookkeeping for a write
129	// that already happened. This local, sub-millisecond step therefore completes
130	// even during shutdown (a second Ctrl-C still force-quits the process).
131	func (s *gitRefsStore) enqueueForPush(ctx context.Context, refName plumbing.ReferenceName) {
132		q, err := PushQueueForRepo(context.WithoutCancel(ctx), s.repo)
133		if err != nil {
134			logging.Warn(ctx, "checkpoint: resolve push queue failed; ref not enqueued",
135				slog.String("ref", refName.String()), slog.String("error", err.Error()))
136			return
137		}
138		if err := q.Enqueue(refName); err != nil {
139			logging.Warn(ctx, "checkpoint: enqueue checkpoint ref for push failed",
140				slog.String("ref", refName.String()), slog.String("error", err.Error()))
141		}
142	}
