261	// applyTranscriptBackfill replaces a session's transcript, prompts, and skill
262	// events on the checkpoint's current subtree, returning the new subtree hash.
263	// Returns ErrCheckpointNotFound when the checkpoint has no sessions yet.
264	func (s *treeWriter) applyTranscriptBackfill(ctx context.Context, opts UpdateOptions, existing *object.Tree, basePath string) (plumbing.Hash, error) {
265		entries, err := s.flattenExisting(existing, basePath)
266		if err != nil {
267			return plumbing.ZeroHash, err
268		}
269	
270		rootMetadataPath := checkpointSubtreePath(basePath, paths.MetadataFileName)
271		entry, exists := entries[rootMetadataPath]
272		if !exists {
273			return plumbing.ZeroHash, ErrCheckpointNotFound
274		}
275	
276		checkpointSummary, err := s.readSummaryFromBlob(entry.Hash)
277		if err != nil {
278			return plumbing.ZeroHash, fmt.Errorf("failed to read checkpoint summary: %w", err)
279		}
280		if len(checkpointSummary.Sessions) == 0 {
281			return plumbing.ZeroHash, ErrCheckpointNotFound
282		}
283	
284		// Find session index matching opts.SessionID
285		sessionIndex := -1
286		var sessionMeta *Metadata
287		for i := range len(checkpointSummary.Sessions) {
288			metaPath := checkpointSubtreePath(basePath, strconv.Itoa(i), paths.MetadataFileName)
289			if metaEntry, metaExists := entries[metaPath]; metaExists {
290				meta, metaErr := s.readMetadataFromBlob(metaEntry.Hash)
291				if metaErr == nil && meta.SessionID == opts.SessionID {
292					sessionIndex = i
293					sessionMeta = meta
294					break
295				}
296			}
297		}
298		if sessionIndex == -1 {
299			// Fall back to latest session; log so mismatches are diagnosable.
300			sessionIndex = len(checkpointSummary.Sessions) - 1
301			logging.Debug(ctx, "backfillTranscript: session ID not found, falling back to latest",
302				slog.String("session_id", opts.SessionID),
303				slog.String("checkpoint_id", string(opts.CheckpointID)),
304				slog.Int("fallback_index", sessionIndex),
305			)
306			metaPath := checkpointSubtreePath(basePath, strconv.Itoa(sessionIndex), paths.MetadataFileName)
307			if metaEntry, metaExists := entries[metaPath]; metaExists {
308				sessionMeta, _ = s.readMetadataFromBlob(metaEntry.Hash) //nolint:errcheck // best-effort; nil meta means start 0
309			}
310		}
311	
312		sessionDir := checkpointSubtreePath(basePath, strconv.Itoa(sessionIndex))
313	
314		// Replace transcript (full replace, not append).
315		// Transcript is pre-redacted by the caller (enforced by RedactedBytes type).
316		if opts.Transcript.Len() > 0 {
317			agentType := opts.Agent
318			startLine := 0
319			if sessionMeta != nil {
320				startLine = sessionMeta.GetTranscriptStart()
321				if agentType == "" {
322					agentType = sessionMeta.Agent
323				}
324			}
325			rewrote, err := s.replaceTranscript(ctx, opts.Transcript, agentType, startLine, opts.PrecomputedBlobs, sessionDir, entries)
326			if err != nil {
327				return plumbing.ZeroHash, fmt.Errorf("failed to replace transcript: %w", err)
328			}
329	
330			// Only touch assets and the root pointers when the transcript was actually
331			// rewritten. If replaceTranscript short-circuited (identical content), the
332			// stored transcript, compact, and assets are all unchanged and already
333			// consistent — clearing/rewriting assets here would strip the blobs a
334			// still-present placeholder depends on, leaving a dangling placeholder.
335			if rewrote {
336				// Keep the externalized image assets consistent with the replaced
337				// transcript: write the new set (clearing any stale ones), so a finalize
338				// that re-externalizes matches its placeholders and one that produces an
339				// inline transcript leaves no orphaned blobs.
340				manifestPath, err := s.writeAssetsForBackfill(opts, sessionDir, entries)
760	
761		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
762		commitMsg := fmt.Sprintf("Update checkpoint summary for %s", checkpointID)
763		_, err := RunRefTransaction(ctx, s.repo, s.refs.Primary, func(parentHash plumbing.Hash) (plumbing.Hash, bool, error) {
764			if parentHash.IsZero() {
765				return plumbing.ZeroHash, false, ErrCheckpointNotFound
766			}
767			rootTreeHash, err := s.rootTreeHashAt(parentHash)
768			if err != nil {
769				return plumbing.ZeroHash, false, err
770			}
771			existing, err := s.subtreeObjAt(rootTreeHash, checkpointID.Path())
772			if err != nil {
773				return plumbing.ZeroHash, false, err
774			}
775			checkpointSubtree, err := s.applyAttributionBackfill(ctx, existing, checkpointID.Path()+"/", combinedAttribution)
776			if err != nil {
777				return plumbing.ZeroHash, false, err
778			}
779			newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, checkpointID, checkpointSubtree)
780			if err != nil {
781				return plumbing.ZeroHash, false, err
782			}
783			newCommitHash, err := CreateCommit(ctx, s.repo, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
784			return newCommitHash, true, err
785		})
786		return err
787	}
