789	// findSessionIndex returns the index of an existing session with the given ID,
790	// or the next available index if not found. This prevents duplicate session entries.
791	func (s *treeWriter) findSessionIndex(ctx context.Context, basePath string, existingSummary *CheckpointSummary, entries map[string]object.TreeEntry, sessionID string) int {
792		if existingSummary == nil {
793			return 0
794		}
795		for i := range len(existingSummary.Sessions) {
796			path := checkpointSubtreePath(basePath, strconv.Itoa(i), paths.MetadataFileName)
797			entry, exists := entries[path]
798			if !exists {
799				continue
800			}
801			meta, err := s.readMetadataFromBlob(entry.Hash)
802			if err != nil {
803				logging.Warn(ctx, "failed to read session metadata during dedup check",
804					slog.Int("session_index", i),
805					slog.String("session_id", sessionID),
806					slog.String("error", err.Error()),
807				)
808				continue
809			}
810			if meta.SessionID == sessionID {
811				return i
812			}
813		}
814		return len(existingSummary.Sessions)
815	}
