817	func (s *treeWriter) findSessionIndexByID(basePath string, entries map[string]object.TreeEntry, summary *CheckpointSummary, sessionID string) (int, error) {
818		for i := range len(summary.Sessions) {
819			path := checkpointSubtreePath(basePath, strconv.Itoa(i), paths.MetadataFileName)
820			entry, exists := entries[path]
821			if !exists {
822				return -1, fmt.Errorf("session metadata not found at %s", path)
823			}
824			meta, err := s.readMetadataFromBlob(entry.Hash)
825			if err != nil {
826				return -1, fmt.Errorf("read session metadata at %s: %w", path, err)
827			}
828			if meta.SessionID == sessionID {
829				return i, nil
830			}
831		}
832		return -1, &SessionNotFoundError{CheckpointID: summary.CheckpointID, SessionID: sessionID}
833	}
