835	// reaggregateFromEntries reads all session metadata from the entries map and
836	// reaggregates CheckpointsCount, FilesTouched, and TokenUsage.
837	func (s *treeWriter) reaggregateFromEntries(basePath string, sessionCount int, entries map[string]object.TreeEntry) (int, []string, *agent.TokenUsage, error) {
838		var totalCount int
839		var allFiles []string
840		var totalTokens *agent.TokenUsage
841	
842		for i := range sessionCount {
843			path := checkpointSubtreePath(basePath, strconv.Itoa(i), paths.MetadataFileName)
844			entry, exists := entries[path]
845			if !exists {
846				return 0, nil, nil, fmt.Errorf("session %d metadata not found at %s", i, path)
847			}
848			meta, err := s.readMetadataFromBlob(entry.Hash)
849			if err != nil {
850				return 0, nil, nil, fmt.Errorf("failed to read session %d metadata: %w", i, err)
851			}
852			totalCount += meta.CheckpointsCount
853			allFiles = mergeFilesTouched(allFiles, meta.FilesTouched)
854			totalTokens = types.AddTokenUsage(totalTokens, meta.TokenUsage)
855		}
856	
857		return totalCount, allFiles, totalTokens, nil
858	}
