605	// GetCheckpointAuthor returns the author of the checkpoint ref's tip commit (the
606	// most recent writer). Returns a zero Author when the ref is absent.
607	func (s *gitRefsStore) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error) {
608		if err := ctx.Err(); err != nil {
609			return Author{}, err //nolint:wrapcheck // Propagating context cancellation
610		}
611		refName, err := RefName(checkpointID)
612		if err != nil {
613			return Author{}, nil //nolint:nilerr // invalid ID → unknown author
614		}
615		ref, err := s.repo.Reference(refName, true)
616		if err != nil {
617			return Author{}, nil //nolint:nilerr // no ref → unknown author
618		}
619		commit, err := s.repo.CommitObject(ref.Hash())
620		if err != nil {
621			return Author{}, nil //nolint:nilerr // unreadable → unknown author
622		}
623		return Author{Name: commit.Author.Name, Email: commit.Author.Email}, nil
624	}

