874	// readJSONFromBlob reads JSON from a blob hash and decodes it to the given type.
875	func readJSONFromBlob[T any](repo *git.Repository, hash plumbing.Hash) (*T, error) {
876		blob, err := repo.BlobObject(hash)
877		if err != nil {
878			return nil, fmt.Errorf("failed to get blob: %w", err)
879		}
880	
881		reader, err := blob.Reader()
882		if err != nil {
883			return nil, fmt.Errorf("failed to get blob reader: %w", err)
884		}
885		defer reader.Close()
886	
887		var result T
888		if err := json.NewDecoder(reader).Decode(&result); err != nil {
889			return nil, fmt.Errorf("failed to decode: %w", err)
890		}
891	
892		return &result, nil
893	}
