 17	// Write dispatches a persistent write request to the matching git operation.
 18	// The request types and Writer interface are defined in the api/checkpoint
 19	// contract (re-exported here via aliases). Unknown request types are a
 20	// programmer error, surfaced rather than ignored.
 21	func (s *GitStore) Write(ctx context.Context, req WriteRequest) error {
 22		return dispatchPersistentWrite(ctx, s, req)
 23	}
 24	
 25	func dispatchPersistentWrite(ctx context.Context, backend persistentWriteBackend, req WriteRequest) error {
 26		switch r := req.(type) {
 27		case Session:
 28			return writeSingleSessionViaBatch(ctx, backend, WriteOptions(r))
 29		case ReservedSession:
 30			return writeSingleSessionViaBatch(ctx, backend, WriteOptions(r))
 31		case BatchSessions:
 32			return backend.writeBatchSessions(ctx, r)
 33		case SessionTranscript:
 34			return backend.backfillTranscript(ctx, UpdateOptions(r))
 35		case SessionSummary:
 36			return backend.backfillSummary(ctx, r)
 37		case CheckpointAttribution:
 38			return backend.backfillAttribution(ctx, r.CheckpointID, r.Attribution)
 39		default:
 40			return fmt.Errorf("checkpoint: unsupported write request %T", req)
 41		}
 42	}
130	func (s *treeWriter) buildCheckpointSubtree(ctx context.Context, entries map[string]object.TreeEntry, basePath string) (plumbing.Hash, error) {
131		relEntries := entries
132		if basePath != "" {
133			relEntries = make(map[string]object.TreeEntry, len(entries))
134			for path, entry := range entries {
135				relPath := strings.TrimPrefix(path, basePath)
136				if relPath == path {
137					continue // Entry doesn't have the expected prefix
138				}
139				relEntries[relPath] = entry
140			}
141		}
142		subtree, err := BuildTreeFromEntries(ctx, s.repo, relEntries)
143		if err != nil {
144			return plumbing.ZeroHash, fmt.Errorf("failed to build checkpoint subtree: %w", err)
145		}
146		return subtree, nil
147	}
