 285	func historyReachesShallowBoundary(ctx context.Context, repoPath, hash string, shallowCommits map[string]struct{}) (bool, error) {
 286		cmd := exec.CommandContext(ctx, "git", "rev-list", hash)
 287		cmd.Dir = repoPath
 288		output, err := cmd.Output()
 289		if err != nil {
 290			return false, fmt.Errorf("git rev-list %s failed: %w", hash, err)
 291		}
 292		for _, commitHash := range strings.Fields(string(output)) {
 293			if _, ok := shallowCommits[commitHash]; ok {
 294				return true, nil
 295			}
 296		}
 297		return false, nil
 298	}
