 314		changed := false
 315		_, err := checkpoint.RunRefTransaction(ctx, repo, refName, func(current plumbing.Hash) (plumbing.Hash, bool, error) {
 316			changed = false
 317			if current == hash {
 318				return current, false, nil
 319			}
