 327				}
 328			}
 329			changed = true
 330			return hash, true, nil
 331		})
 332		if err != nil {
 333			return false, fmt.Errorf("replace data-free metadata ref %s: %w", refName, err)
 334		}
 335		return changed, nil
 336	}
