 901	// bootstrapPrimaryFromCheckpointRemote tries to populate a missing local primary
 902	// metadata ref from a configured checkpoint_remote before the caller falls back
 903	// to creating an empty orphan. When a separate checkpoint_remote already holds
 904	// the real entire/checkpoints/v1 branch (the common second-device case), a fresh
 905	// local orphan would diverge from it — hiding existing checkpoints and causing
 906	// non-fast-forward rejections on the next fetch.
 907	//
 908	// All resolution is pinned to repo's worktree (settings, origin URL, fetch
 909	// working directory, ref promotion) so the decision depends on the repository
 910	// being ensured rather than the ambient working directory.
 911	//
 912	// It returns true only when the fetch succeeds and the local primary ref now
 913	// points at the remote branch. Every failure is non-fatal and returns false so
 914	// the caller creates the empty orphan: `entire enable` must never break on a
 915	// missing checkpoint remote, an unresolvable URL, or a network/auth error.
 916	func bootstrapPrimaryFromCheckpointRemote(ctx context.Context, repo *git.Repository, primary plumbing.ReferenceName, primaryIsRefs bool) bool {
 917		if !checkpointRemoteBootstrapAllowed(ctx) {
 918			// Not an explicit setup flow (e.g. the per-turn hook hot path via
 919			// EnsureSetup). Never fetch here: hook execution has a hard timeout,
 920			// and a slow/unreachable checkpoint remote must not stall every turn.
 921			// Fall back to the empty orphan, which self-heals immediately.
 922			logging.Debug(ctx, "checkpoint-remote: skipping bootstrap fetch outside explicit enable flow")
 923			return false
 924		}
 925	
 926		if primaryIsRefs {
 927			// The whole point of this bootstrap is to stop a fresh local orphan from
 928			// diverging from the real v1 branch. Under the git-refs primary backend
 929			// no orphan is ever created and nothing is ever written to v1, so there
 930			// is no divergence to prevent and the fetch buys nothing at enable time.
 930			// is no divergence to prevent and the fetch buys nothing at enable time.
 931			//
 932			// It is not free, either: v1 holds the full legacy transcript history, so
 933			// this would make every `entire enable` on a fresh clone download the
 934			// entire checkpoint archive before doing anything else. Legacy hex-ID
 935			// checkpoints stay readable — the read path recovers the branch on demand
 936			// (checkpoint.MetadataBranchFetchFunc), fetching individual blobs by hash
 937			// rather than the whole archive.
 938			logging.Debug(ctx, "checkpoint-remote: skipping bootstrap fetch under git-refs primary")
 939			return false
 940		}
 941	
 942		worktreeRoot, err := getRepoPath(repo)
 943		if err != nil {
 944			logging.Debug(ctx, "checkpoint-remote: cannot resolve worktree root for enable bootstrap",
 945				slog.String("error", err.Error()),
 946			)
 947			return false
 948		}
 949		// Pin settings/remote resolution to this repo's worktree.
 950		ctx = settings.WithWorktreeRoot(ctx, worktreeRoot)
 951	
 952		// Resolve and verify the checkpoint fetch URL. resolveCheckpointFetchURL
 953		// rejects remote.FetchURL's silent origin fallback, so bootstrap never adopts
 954		// origin's data when the derived URL doesn't actually target the configured
 955		// checkpoint repo (issue #1374).
 956		url, ok := resolveCheckpointFetchURL(ctx, worktreeRoot)
 957		if !ok {
 958			return false
 959		}
 960	
 961		branchName := primary.Short()
 962		tmpRefName := plumbing.ReferenceName(FetchTmpRefPrefix + branchName)
 963		// Unfiltered. The bootstrap itself only needs the ref, but it is only ever
 964		// reached under the git-branch primary (git-refs returns above), and there
 965		// the branch it lands IS the repo's checkpoint store — refs.Read and
 966		// refs.Primary are the same v1 branch. GitStore.List reads each checkpoint's
 967		// metadata.json through a plain tree with no blob fetcher, and once this ref
 968		// resolves the recovery tier never fires again, so a blob-filtered bootstrap
 969		// would leave `checkpoint list` permanently showing bare IDs with no prompt,
 970		// date, or counts.
 971		if err := fetchURLIntoTmpRef(ctx, worktreeRoot, url, primary.String(), tmpRefName.String(), "metadata branch", true, checkpointRemoteForegroundFetchTimeout); err != nil {
 972			// Warn, not Debug: `entire enable` is an explicit user action, and this
 973			// failure means existing checkpoints stay unreachable until a read
 974			// re-fetches them. At Debug the command looked like it had simply
 975			// paused, then succeeded.
 976			logging.Warn(ctx, "checkpoint-remote: enable bootstrap fetch failed; creating empty orphan",
 977				slog.String("url", remote.RedactURL(url)),
 978				slog.String("error", err.Error()),
 979			)
 980			fmt.Fprintf(os.Stderr, "  ! Could not fetch existing checkpoints from %s\n", remote.RedactURL(url))
 981			fmt.Fprintln(os.Stderr, "    Continuing — they will be fetched on demand when a command needs them.")
 982			return false
 983		}
 984		defer func() { _ = repo.Storer.RemoveReference(tmpRefName) }() //nolint:errcheck // cleanup is best-effort
 985	
 986		tmpRef, err := repo.Reference(tmpRefName, true)
 987		if err != nil {
 988			logging.Debug(ctx, "checkpoint-remote: fetched metadata ref missing after enable bootstrap",
 989				slog.String("error", err.Error()),
 990			)
 991			return false
 992		}
 993		if err := SafelyAdvanceLocalRef(ctx, repo, primary, tmpRef.Hash()); err != nil {
 994			logging.Debug(ctx, "checkpoint-remote: could not advance local metadata ref on enable bootstrap",
 995				slog.String("error", err.Error()),
 996			)
 997			return false
 998		}
 999		logging.Info(ctx, "checkpoint-remote: bootstrapped metadata branch on enable",
1000			slog.String("ref", primary.String()),
1001		)
1002		return true
1003	}
