1005	// healPrimaryFromCheckpointRemote replaces a local primary metadata ref that holds
1006	// no checkpoint data — an empty orphan, or a vercel.json-only orphan on a
1007	// vercel-enabled repo — with the real branch fetched from a configured
1008	// checkpoint_remote. It repairs second-device repos left with an un-initialized
1009	// orphan disjoint from the remote history (issue #1374).
1010	//
1011	// The network fetch is gated on an explicit enable flow
1012	// (WithCheckpointRemoteBootstrap); the per-turn hook hot path stays network-free.
1013	// Returns true only when the local ref was replaced with real remote data. A
1014	// local branch that already carries checkpoints, a non-enable context, an
1015	// unresolvable URL, or a fetch that yields no usable data all return (false, nil)
1016	// so the caller keeps the local ref as-is.
1017	func healPrimaryFromCheckpointRemote(ctx context.Context, repo *git.Repository, localRef *plumbing.Reference, primary plumbing.ReferenceName) (bool, error) {
