 1	// Package validation provides input validation functions for the Entire CLI.
 2	// This package has no dependencies to avoid import cycles.
 3	package validation
 4	
 5	import (
 6		"errors"
 7		"fmt"
 8		"path/filepath"
 9		"regexp"
10		"strings"
11	)
12	
13	// pathSafeRegex matches alphanumeric characters, underscores, and hyphens only.
14	// Used to validate IDs that will be used in file paths.
15	var pathSafeRegex = regexp.MustCompile(`^[a-zA-Z0-9_-]+$`)
16	
17	// ValidateSessionID validates that a session ID doesn't contain path separators
18	// or other unsafe characters for use in file paths.
19	// This prevents path traversal attacks when session IDs are used in file paths.
20	func ValidateSessionID(id string) error {
21		if strings.TrimSpace(id) == "" {
22			return errors.New("session ID cannot be empty")
23		}
24		if strings.HasPrefix(id, "-") {
25			return fmt.Errorf("invalid session ID %q: starts with dash", id)
26		}
27		if strings.ContainsAny(id, "/\\") {
28			return fmt.Errorf("invalid session ID %q: contains path separators", id)
29		}
30		// A bare "." or ".." is separator-free but still traverses when used as a
31		// path segment (e.g. an agent that uses the ID as a directory component).
32		if id == "." || id == ".." {
33			return fmt.Errorf("invalid session ID %q: reserved path segment", id)
34		}
35		// Reject the Windows volume separator. A drive-relative path like "C:foo" is
36		// separator-free and filepath.IsAbs reports it as non-absolute, yet
37		// filepath.Join discards the base directory when the appended element
38		// carries a volume name — escaping the intended directory on Windows.
39		if strings.Contains(id, ":") {
40			return fmt.Errorf("invalid session ID %q: contains volume separator", id)
41		}
42		// Reject glob metacharacters. Session IDs are interpolated into
43		// filepath.Glob patterns in several places (agent transcript lookup,
44		// session-state cleanup); "*"/"?"/"[" could match and act on unrelated files.
45		if strings.ContainsAny(id, "*?[") {
46			return fmt.Errorf("invalid session ID %q: contains glob metacharacters", id)
47		}
48		// Defense in depth against platform-specific absolute forms (e.g. Windows
49		// drive paths) that the separator check above may not catch.
50		if filepath.IsAbs(id) || filepath.VolumeName(id) != "" {
51			return fmt.Errorf("invalid session ID %q: must not be an absolute path", id)
52		}
53		return nil
54	}
55	
56	// ValidateToolUseID validates that a tool use ID contains only safe characters for paths.
57	// Tool use IDs can be UUIDs or prefixed identifiers like "toolu_xxx".
58	func ValidateToolUseID(id string) error {
59		if id == "" {
60			return nil // Empty is allowed (optional field)
61		}
62		if !pathSafeRegex.MatchString(id) {
63			return fmt.Errorf("invalid tool use ID %q: must be alphanumeric with underscores/hyphens only", id)
64		}
65		return nil
66	}
67	
68	// ValidateAgentID validates that an agent ID contains only safe characters for paths.
69	func ValidateAgentID(id string) error {
70		if id == "" {
71			return nil // Empty is allowed (optional field)
72		}
73		if !pathSafeRegex.MatchString(id) {
74			return fmt.Errorf("invalid agent ID %q: must be alphanumeric with underscores/hyphens only", id)
75		}
76		return nil
77	}
78	
79	// ValidateAgentSessionID validates that an agent session ID contains only safe characters for paths.
80	// Agent session IDs can be UUIDs (Claude Code), test identifiers, or other formats depending on the agent.
81	// This prevents path traversal attacks when the ID is used in file path construction.
82	func ValidateAgentSessionID(id string) error {
83		if id == "" {
84			return errors.New("agent session ID cannot be empty")
85		}
86		if strings.HasPrefix(id, "-") {
87			return fmt.Errorf("invalid agent session ID %q: starts with dash", id)
88		}
89		if !pathSafeRegex.MatchString(id) {
90			return fmt.Errorf("invalid agent session ID %q: must be alphanumeric with underscores/hyphens only", id)
91		}
92		return nil
93	}

