package checkpoint

import (
	"context"
	"errors"
	"fmt"
	"math/rand/v2"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/internal/flock"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

// ErrShadowRefBusy is returned by casUpdateShadowBranchRef when the ref has
// moved since the caller read it. Callers retry with a fresh parent.
var ErrShadowRefBusy = errors.New("shadow branch ref moved (CAS mismatch)")

// ErrShadowBranchMoved means the caller's base no longer names the current
// shadow branch and migration must be retried before publishing.
var ErrShadowBranchMoved = errors.New("shadow branch base changed during write")

// shadowRefMaxRetries bounds the WriteTemporary retry loop. With the
// per-shadow-branch flock held, our own writers never collide; this budget
// is purely a safety net against an external `git update-ref` writer that
// repeatedly beats us to the ref.
const shadowRefMaxRetries = 16

// shadowRefMaxJitter is the upper bound for randomized backoff between CAS
// retries. Random jitter avoids thundering-herd retry patterns when many
// sessions hit the same shadow branch simultaneously.
const shadowRefMaxJitter = 8 * time.Millisecond

// repoCommonDir returns the git common dir used for shadow-ref locks and loose
// object cleanup without depending on the process working directory.
func (s *ephemeralStore) repoCommonDir(ctx context.Context) (string, error) {
	commonDir, err := resolveGitCommonDir(ctx, s.repo)
	if err != nil {
		return "", err
	}
	return commonDir, nil
}

// casUpdateShadowBranchRef atomically updates a shadow branch ref via
// `git update-ref <ref> <new> <old>`. Pass plumbing.ZeroHash as expectedHash
// to require the ref to NOT exist (first-checkpoint case).
//
// Returns ErrShadowRefBusy when git reports the ref moved since expectedHash
// was observed; callers retry with a fresh parent. Any other failure is
// returned wrapped.
//
// Why shell out: git's ref-locking is the canonical cross-process atomic
// CAS — go-git's CheckAndSetReference doesn't interoperate with native git's
// .lock files, and shadow branches can be touched concurrently by separate
// `entire` hook processes.
func casUpdateShadowBranchRef(ctx context.Context, repo *git.Repository, branchName string, newHash, expectedHash plumbing.Hash) error {
	err := CompareAndSwapRef(ctx, repo, plumbing.NewBranchReferenceName(branchName), newHash, expectedHash)
	if errors.Is(err, ErrRefConflict) {
		return ErrShadowRefBusy
	}
	return err
}

// shadowRefBackoff sleeps for a small random jitter before the next CAS
// retry. After several retries the upper bound doubles to slow the
// thundering herd further. Respects context cancellation.
func shadowRefBackoff(ctx context.Context, attempt int) error {
	base := shadowRefMaxJitter
	if attempt > 4 {
		base *= 2
	}
	// Add a 1ms floor so the chosen sleep is always non-trivial, even when
	// rand.Int64N happens to return 0.
	d := time.Duration(rand.Int64N(int64(base))) + time.Millisecond //nolint:gosec // jitter, not security-sensitive
	select {
	case <-time.After(d):
		return nil
	case <-ctx.Done():
		return ctx.Err() //nolint:wrapcheck // canonical context cancellation
	}
}

// shadowBranchLockPath returns the per-shadow-branch flock file path. Lock
// files live in <git-common-dir>/entire-shadow-locks/ so they don't pollute
// the session-state directory. Branch names are slash-escaped because the
// shadow-branch convention "entire/<hash>" would otherwise nest directories.
func shadowBranchLockPath(commonDir, branchName string) (string, error) {
	lockDir := filepath.Join(commonDir, "entire-shadow-locks")
	if err := os.MkdirAll(lockDir, 0o750); err != nil {
		return "", fmt.Errorf("create shadow lock directory: %w", err)
	}
	safe := strings.ReplaceAll(branchName, "/", "_")
	return filepath.Join(lockDir, safe+".lock"), nil
}

// withShadowBranchFlock acquires the per-shadow-branch flock, runs fn, and
// releases the flock. Serializes all WriteTemporary callers that target the
// same shadow branch — across goroutines AND across processes — so the CAS
// in casUpdateShadowBranchRef only sees external writers as contention.
//
// commonDir is the git common directory (from s.repoDirs); it locates the
// lock file independently of the process cwd.
func withShadowBranchFlock(commonDir, branchName string, fn func() error) error {
	return withShadowBranchFlocks(commonDir, []string{branchName}, fn)
}

func withShadowBranchFlocks(commonDir string, branchNames []string, fn func() error) error {
	ordered := append([]string(nil), branchNames...)
	sort.Strings(ordered)
	unique := ordered[:0]
	for _, branchName := range ordered {
		if len(unique) == 0 || unique[len(unique)-1] != branchName {
			unique = append(unique, branchName)
		}
	}

	releases := make([]func(), 0, len(unique))
	for _, branchName := range unique {
		path, err := shadowBranchLockPath(commonDir, branchName)
		if err != nil {
			for i := len(releases) - 1; i >= 0; i-- {
				releases[i]()
			}
			return err
		}
		release, err := flock.Acquire(path)
		if err != nil {
			for i := len(releases) - 1; i >= 0; i-- {
				releases[i]()
			}
			return fmt.Errorf("acquire shadow flock %s: %w", branchName, err)
		}
		releases = append(releases, release)
	}
	defer func() {
		for i := len(releases) - 1; i >= 0; i-- {
			releases[i]()
		}
	}()
	return fn()
}

// MoveShadowBranchIfUnchanged locks both shadow branches before moving their
// refs atomically.
func MoveShadowBranchIfUnchanged(
	ctx context.Context,
	repo *git.Repository,
	sourceBranch, destinationBranch string,
	expectedSource plumbing.Hash,
) error {
	commonDir, err := resolveGitCommonDir(ctx, repo)
	if err != nil {
		return err
	}
	return withShadowBranchFlocks(commonDir, []string{sourceBranch, destinationBranch}, func() error {
		return MoveRefIfUnchanged(ctx, repo,
			plumbing.NewBranchReferenceName(sourceBranch),
			plumbing.NewBranchReferenceName(destinationBranch),
			expectedSource)
	})
}

// tryDeleteLooseObject best-effort removes a loose object file. Used to
// clean up dangling commits created during a CAS-losing attempt. Failures
// (e.g. object already packed by a concurrent gc, or never written as a
// loose object) are ignored — the object will be picked up by the next gc
// pass either way.
func tryDeleteLooseObject(commonDir string, hash plumbing.Hash) {
	h := hash.String()
	if len(h) < 3 {
		return
	}
	_ = os.Remove(filepath.Join(commonDir, "objects", h[:2], h[2:]))
}
package strategy

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"path/filepath"
	"sort"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/trailers"
	"github.com/entireio/cli/perf"

	"github.com/go-git/go-git/v6"
)

// SaveStep saves a checkpoint to the shadow branch.
// Uses checkpoint.EphemeralStore.Write with a checkpoint.Step request.
func (s *ManualCommitStrategy) SaveStep(ctx context.Context, step StepContext) error {
	_, openRepoSpan := perf.Start(ctx, "open_repository")
	repo, err := OpenRepository(ctx)
	if err != nil {
		openRepoSpan.RecordError(err)
		openRepoSpan.End()
		return fmt.Errorf("failed to open git repository: %w", err)
	}
	defer repo.Close()
	openRepoSpan.End()

	sessionID := filepath.Base(step.MetadataDir)

	// Initialize the session if no state exists yet. Done outside
	// MutateSessionState because the helper bails with ErrStateNotFound on
	// missing state — initialization establishes the file the helper will
	// then mutate under lock.
	if err := s.ensureSessionInitialized(ctx, repo, sessionID, step.AgentType); err != nil {
		return err
	}

	mutErr := MutateSessionState(ctx, sessionID, func(state *SessionState) error {
		_, migrateSpan := perf.Start(ctx, "migrate_shadow_branch")
		if _, _, err := s.migrateShadowBranchIfNeeded(ctx, repo, state); err != nil {
			migrateSpan.RecordError(err)
			migrateSpan.End()
			return fmt.Errorf("failed to check/migrate shadow branch: %w", err)
		}
		migrateSpan.End()

		store, err := s.getEphemeralStore(ctx, repo)
		if err != nil {
			return err
		}

		shadowBranchName := ""
		branchExisted := false

		var promptAttr PromptAttribution
		if state.PendingPromptAttribution != nil {
			promptAttr = *state.PendingPromptAttribution
			state.PendingPromptAttribution = nil
		} else {
			promptAttr = PromptAttribution{CheckpointNumber: state.StepCount + 1}
		}

		attrLogCtx := logging.WithComponent(ctx, "attribution")
		logging.Debug(attrLogCtx, "prompt attribution at checkpoint save",
			slog.Int("checkpoint_number", promptAttr.CheckpointNumber),
			slog.Int("user_added", promptAttr.UserLinesAdded),
			slog.Int("user_removed", promptAttr.UserLinesRemoved),
			slog.Int("agent_added", promptAttr.AgentLinesAdded),
			slog.Int("agent_removed", promptAttr.AgentLinesRemoved),
			slog.String("session_id", sessionID))

		_, writeCheckpointSpan := perf.Start(ctx, "write_temporary_checkpoint")
		isFirstCheckpointOfSession := state.StepCount == 0
		var result checkpoint.WriteEphemeralResult
		for attempt := range 2 {
			shadowBranchName = checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
			branchExisted = store.ShadowBranchExists(state.BaseCommit, state.WorktreeID)
			result, err = store.Write(ctx, checkpoint.Step{
				SessionID:         sessionID,
				BaseCommit:        state.BaseCommit,
				WorktreeID:        state.WorktreeID,
				ModifiedFiles:     step.ModifiedFiles,
				NewFiles:          step.NewFiles,
				DeletedFiles:      step.DeletedFiles,
				MetadataDir:       step.MetadataDir,
				MetadataDirAbs:    step.MetadataDirAbs,
				CommitMessage:     step.CommitMessage,
				AuthorName:        step.AuthorName,
				AuthorEmail:       step.AuthorEmail,
				IsFirstCheckpoint: isFirstCheckpointOfSession,
			})
			if !errors.Is(err, checkpoint.ErrShadowBranchMoved) || attempt == 1 {
				break
			}
			if _, _, migrateErr := s.migrateShadowBranchIfNeeded(ctx, repo, state); migrateErr != nil {
				err = fmt.Errorf("failed to retry shadow branch migration: %w", migrateErr)
				break
			}
		}
		writeCheckpointSpan.RecordError(err)
		writeCheckpointSpan.End()
		if err != nil {
			return fmt.Errorf("failed to write temporary checkpoint: %w", err)
		}

		if result.Skipped {
			logCtx := logging.WithComponent(ctx, "checkpoint")
			logging.Info(logCtx, "checkpoint skipped (no changes)",
				slog.String("strategy", "manual-commit"),
				slog.String("checkpoint_type", "session"),
				slog.Int("checkpoint_count", state.StepCount),
				slog.String("shadow_branch", shadowBranchName),
			)
			return ErrMutationSkip
		}

		// LastCheckpointID is intentionally NOT cleared here. It is set during
		// condensation and used by handleAmendCommitMsg to restore checkpoint
		// trailers on amend operations.
		state.StepCount++
		state.PromptAttributions = append(state.PromptAttributions, promptAttr)
		state.FilesTouched = mergeFilesTouched(state.FilesTouched, step.ModifiedFiles, step.NewFiles, step.DeletedFiles)
		if state.StepCount == 1 {
			state.TranscriptIdentifierAtStart = step.StepTranscriptIdentifier
		}
		if step.TokenUsage != nil {
			state.TokenUsage = accumulateTokenUsage(state.TokenUsage, step.TokenUsage)
			state.CheckpointTokenUsage = accumulateTokenUsage(state.CheckpointTokenUsage, step.TokenUsage)
			// step.TokenUsage.SubagentTokens is a cumulative-since-session-start
			// snapshot (agent IDs are discovered from the full transcript and each
			// subagent's own transcript is re-read from its start on every call —
			// see CalculateTotalTokenUsage in the claudecode/factoryaidroid
			// packages), not a per-step delta like the rest of TokenUsage.
			// accumulateTokenUsage already replaces (rather than adds) the
			// SubagentTokens field for that reason, so state.TokenUsage ends up
			// correctly holding the latest cumulative total. CheckpointTokenUsage
			// additionally needs rescoping to "since last condensation" by
			// subtracting the baseline captured at the last reset, otherwise the
			// full cumulative subagent total would be reported again at every
			// checkpoint instead of just this checkpoint's share.
