// the session-state directory. Branch names are slash-escaped because the
// shadow-branch convention "entire/<hash>" would otherwise nest directories.
func shadowBranchLockPath(commonDir, branchName string) (string, error) {
	lockDir := filepath.Join(commonDir, "entire-shadow-locks")
	if err := os.MkdirAll(lockDir, 0o750); err != nil {
		return "", fmt.Errorf("create shadow lock directory: %w", err)
	}
	safe := strings.ReplaceAll(branchName, "/", "_")
	return filepath.Join(lockDir, safe+".lock"), nil
}

// withShadowBranchFlock acquires the per-shadow-branch flock, runs fn, and
// releases the flock. Serializes all WriteTemporary callers that target the
// same shadow branch — across goroutines AND across processes — so the CAS
// in casUpdateShadowBranchRef only sees external writers as contention.
//
// commonDir is the git common directory (from s.repoDirs); it locates the
// lock file independently of the process cwd.
func withShadowBranchFlock(commonDir, branchName string, fn func() error) error {
	return withShadowBranchFlocks(commonDir, []string{branchName}, fn)
}

func withShadowBranchFlocks(commonDir string, branchNames []string, fn func() error) error {
	ordered := append([]string(nil), branchNames...)
	sort.Strings(ordered)
	unique := ordered[:0]
	for _, branchName := range ordered {
		if len(unique) == 0 || unique[len(unique)-1] != branchName {
			unique = append(unique, branchName)
		}
	}

	releases := make([]func(), 0, len(unique))
	for _, branchName := range unique {
		path, err := shadowBranchLockPath(commonDir, branchName)
		if err != nil {
			for i := len(releases) - 1; i >= 0; i-- {
				releases[i]()
			}
			return err
		}
		release, err := flock.Acquire(path)
		if err != nil {
			for i := len(releases) - 1; i >= 0; i-- {
				releases[i]()
			}
			return fmt.Errorf("acquire shadow flock %s: %w", branchName, err)
		}
		releases = append(releases, release)
	}
	defer func() {
		for i := len(releases) - 1; i >= 0; i-- {
			releases[i]()
		}
	}()
	return fn()
}

// MoveShadowBranchIfUnchanged locks both shadow branches before moving their
// refs atomically.
func MoveShadowBranchIfUnchanged(
	ctx context.Context,
	repo *git.Repository,
	sourceBranch, destinationBranch string,
	expectedSource plumbing.Hash,
) error {
	commonDir, err := resolveGitCommonDir(ctx, repo)
	if err != nil {
		return err
	}
	return withShadowBranchFlocks(commonDir, []string{sourceBranch, destinationBranch}, func() error {
		return MoveRefIfUnchanged(ctx, repo,
			plumbing.NewBranchReferenceName(sourceBranch),
			plumbing.NewBranchReferenceName(destinationBranch),
			expectedSource)
	})
}

// tryDeleteLooseObject best-effort removes a loose object file. Used to
// clean up dangling commits created during a CAS-losing attempt. Failures
// (e.g. object already packed by a concurrent gc, or never written as a
// loose object) are ignored — the object will be picked up by the next gc
// pass either way.
func tryDeleteLooseObject(commonDir string, hash plumbing.Hash) {
	h := hash.String()
	if len(h) < 3 {
		return
	}
	_ = os.Remove(filepath.Join(commonDir, "objects", h[:2], h[2:]))
}
	if commonDir == "" {
		return "", fmt.Errorf("empty git common dir for %s", worktreePath)
	}
	if !filepath.IsAbs(commonDir) {
		commonDir = filepath.Join(worktreePath, commonDir)
	}
	commonDir = filepath.Clean(commonDir)
	if resolved, err := filepath.EvalSymlinks(commonDir); err == nil {
		commonDir = resolved
	}
	return commonDir, nil
}

func isNestedWorktreeOfRecordedRepo(recordedWorktreePath, commitWorktreePath string) bool {
	nestedWorktreesDir := filepath.Join(filepath.Clean(recordedWorktreePath), ".worktrees")
	return paths.IsSubpath(nestedWorktreesDir, filepath.Clean(commitWorktreePath))
}

type rewritePair struct {
	OldSHA string
	NewSHA string
}

func remapRewriteSHA(sha string, rewrites []rewritePair) (string, bool) {
	for _, pair := range rewrites {
		if sha == pair.OldSHA {
			return pair.NewSHA, true
		}
	}
	return sha, false
}

func shadowBranchExistsForBaseCommit(repo *git.Repository, baseCommit, worktreeID string) bool {
	if repo == nil || baseCommit == "" {
		return false
	}

	refName := plumbing.NewBranchReferenceName(checkpoint.ShadowBranchNameForCommit(baseCommit, worktreeID))
	_, err := repo.Reference(refName, true)
	return err == nil
}

func (s *ManualCommitStrategy) remapSessionForRewrite(ctx context.Context, repo *git.Repository, state *SessionState, rewrites []rewritePair) (bool, error) {
	if state == nil {
		return false, nil
	}

	newBaseCommit, baseChanged := remapRewriteSHA(state.BaseCommit, rewrites)
	newAttrBaseCommit, attrChanged := remapRewriteSHA(state.AttributionBaseCommit, rewrites)
	if !baseChanged && !attrChanged {
		return false, nil
	}

	hadShadowBranch := shadowBranchExistsForBaseCommit(repo, state.BaseCommit, state.WorktreeID)
	if baseChanged {
		changed, err := s.migrateShadowBranchToBaseCommit(ctx, repo, state, newBaseCommit)
		if err != nil {
			return false, fmt.Errorf("failed to migrate rewritten shadow branch: %w", err)
		}
		baseChanged = changed
	}

	// If a shadow branch existed, preserve AttributionBaseCommit so future
	// attribution still diffs against the original checkpoint base captured on
	// that branch. Without a shadow branch, keep attribution in sync with the
	// rewritten commit lineage.
	if attrChanged && !hadShadowBranch {
		state.AttributionBaseCommit = newAttrBaseCommit
	}

	return baseChanged || attrChanged, nil
}

// findSessionsForCommit finds all sessions where base_commit matches the given SHA.
func (s *ManualCommitStrategy) findSessionsForCommit(ctx context.Context, baseCommitSHA string) ([]*SessionState, error) {
	allStates, err := s.listAllSessionStates(ctx)
	if err != nil {
		return nil, err
	}

	var matching []*SessionState
	for _, state := range allStates {
		if state.BaseCommit == baseCommitSHA {
			matching = append(matching, state)
		}
	}
	return matching, nil
}

// FindSessionsForCommit is the exported version of findSessionsForCommit.
// Used by the rewind reset command to find sessions to clean up.
func (s *ManualCommitStrategy) FindSessionsForCommit(ctx context.Context, baseCommitSHA string) ([]*SessionState, error) {
	return s.findSessionsForCommit(ctx, baseCommitSHA)
}

